const form = document.getElementById('quiz-form');
const scoreElement = document.querySelector('[data-testid="quiz-score"]');
const message = document.getElementById('form-message');
const answers = { q1: 'mars', q2: 'pacific', q3: 'six' };
const questionNames = Object.keys(answers);

form.addEventListener('submit', (event) => {
  event.preventDefault();
  const selectedAnswers = questionNames.reduce((selections, name) => {
    const selected = form.querySelector(`input[name="${name}"]:checked`);
    selections[name] = selected ? selected.value : '';
    return selections;
  }, {});
  const unanswered = questionNames.filter((name) => !selectedAnswers[name]);

  if (unanswered.length) {
    message.textContent = 'Please choose one answer for each question.';
    return;
  }

  let score = 0;
  questionNames.forEach((question) => {
    if (selectedAnswers[question] === answers[question]) score += 1;
  });

  scoreElement.textContent = String(score);
  scoreElement.dataset.score = String(score);
  message.textContent = score === 3 ? 'Perfect score — excellent work!' : 'Answer recorded. You can change your choices and submit again.';
});

form.addEventListener('change', () => {
  message.textContent = '';
});

